#include <stdio.h>

struct Disk {
    int capacity;  // in GB
    float speed;   // in RPM
};

int main() {
    struct Disk myDisk;
    myDisk.capacity = 500;
    myDisk.speed = 7200.0;
    printf("Disk capacity: %d GB\n", myDisk.capacity);
    printf("Disk speed: %.2f RPM\n", myDisk.speed);
    return 0;
}
